SELECT sku, gtin, name, pack, case_units, case_kg, flow, price_inr
FROM store.products
ORDER BY sku;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY table_schema, table_name;

SELECT table_name, column_name, data_type
FROM information_schema.columns
WHERE table_schema='warehouse' ORDER BY table_name, ordinal_position;

SELECT sku, count(*) FILTER (WHERE units_sold=0) AS zero_days, count(*) AS days, sum(units_sold) AS units
FROM store.daily_sales WHERE date BETWEEN '2026-06-01' AND '2026-06-30'
GROUP BY sku ORDER BY sku;
